  let x, y;
  let placed = false;

  if (!narrow) {
    // Try right of anchor
    x = ar.right + GAP;
    y = ar.top + (ar.height / 2) - (th / 2);
    if (x + tw + MARGIN <= vw && y >= MARGIN && y + th + MARGIN <= vh) {
      placed = true;
    }
    // Try left of anchor
    if (!placed) {
      x = ar.left - GAP - tw;
      y = ar.top + (ar.height / 2) - (th / 2);
