  if (!placed) {
    x = ar.left + (ar.width / 2) - (tw / 2);
    y = ar.top - GAP - th;
    if (y >= MARGIN) {
      placed = true;
    }
  }

  // Fallback: below anchor
  if (!placed) {
    x = ar.left + (ar.width / 2) - (tw / 2);
    y = ar.bottom + GAP;
  }

